import './neon-badge.scss';
import { NeonWidget } from '../shared/neon-widget';
import { dynamicText, createElement, updateDynamicText, updateDynamicAttribute, dynamicAttr } from '../shared/dom-manipulation';
export class NeonBadge extends NeonWidget {
    constructor() {
        super(...arguments);
        this.widgetTag = 'neon-badge';
    }
    //Any attribute that should be watched for changes should be listed here.
    static get observedAttributes() {
        return [
            'data-type',
            'data-count',
            'data-overflow-count',
            'data-show-zero',
        ];
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        switch (attrName) {
            case 'data-type':
                updateDynamicAttribute(this, 'class');
                break;
            case 'data-count':
                updateDynamicText(this);
                break;
            case 'data-overflow-count':
                updateDynamicText(this);
                break;
            case 'data-show-zero':
                updateDynamicText(this);
                break;
            default:
        }
    }
    getBadgeCount() {
        if (this.getAttribute('data-count') != null) {
            return Number(this.getAttribute('data-count'));
        }
    }
    getBadgeText() {
        let badgeText = '';
        const overflowCount = Number(this.getAttribute('data-overflow-count')) || 99;
        const badgeCount = this.getBadgeCount();
        if (badgeCount != null) {
            if (badgeCount > overflowCount) {
                badgeText = overflowCount + '+';
            }
            else {
                badgeText = String(this.getBadgeCount());
            }
            if (badgeText === '0' && this.getAttribute('data-show-zero') !== 'true') {
                return;
            }
            return badgeText;
        }
    }
    // the default is neon-badge-navy if a type is not provided
    getBadgeClass() {
        let badgeClasses = 'neon-badge';
        if (this.getAttribute('data-type') != null) {
            badgeClasses += ' neon-badge-' + this.getAttribute('data-type');
        }
        else {
            badgeClasses += ' neon-badge-navy';
        }
        return badgeClasses;
    }
    render() {
        return createElement('span', {
            attrs: {
                class: dynamicAttr(() => { return this.getBadgeClass(); })
            },
            text: dynamicText(() => { return this.getBadgeText(); })
        });
    }
}
